SELECT id, full_name, manager_id, salary, hire_date, is_remote, level, MIN(salary) OVER (PARTITION BY level, job_title ORDER BY hire_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_salary, MAX(salary) OVER (PARTITION BY level, job_title ORDER BY hire_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_max_salary, COUNT(salary) OVER (PARTITION BY level, job_title ORDER BY hire_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_count_salary, SUM(salary) OVER (PARTITION BY level, job_title ORDER BY hire_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum_salary FROM employees WHERE salary < 137000
